package xrefgo

import (
	"strings"

	ts "github.com/tree-sitter/go-tree-sitter"
)

// A Rails scope is a class-level method generated by ActiveRecord. Its lambda
// is indexed as a candidate body; no Rails constant loading or SQL execution
// is involved.
func scanRailsScopes(path string, src []byte, models map[string]ModelInfo) ([]Method, []Ref) {
	if !strings.HasPrefix(path, "app/models/") {
		return nil, nil
	}
	p, tree, err := rubyTree(src)
	if err != nil {
		return nil, nil
	}
	defer p.Close()
	defer tree.Close()
	methods, refs := []Method{}, []Ref{}
	var walk func(*ts.Node, string, string)
	walk = func(n *ts.Node, namespace, owner string) {
		switch n.Kind() {
		case "module", "class":
			name := fieldText(n, "name", src)
			if name != "" {
				if namespace != "" && !strings.Contains(name, "::") {
					name = namespace + "::" + name
				}
				name = strings.TrimPrefix(name, "::")
				if n.Kind() == "module" {
					namespace = name
					owner = ""
				} else {
					owner = name
					namespace = name
				}
			}
		case "method", "singleton_method":
			return
		case "call":
			if owner != "" && fieldText(n, "method", src) == "scope" && n.ChildByFieldName("receiver") == nil {
				args := n.ChildByFieldName("arguments")
				if args != nil && args.NamedChildCount() > 0 {
					nameNode := args.NamedChild(0)
					if nameNode.Kind() == "simple_symbol" || nameNode.Kind() == "string" {
						name := unquoteRoute(nameNode.Utf8Text(src))
						if scopeName(name) {
							info := models[owner]
							if info.Table != "" {
								methods = append(methods, Method{Owner: owner, Name: name, Class: true, Path: path, Line: int(n.StartPosition().Row) + 1, EndLine: int(n.EndPosition().Row) + 1, Kind: "scope"})
								for i := uint(1); i < args.NamedChildCount(); i++ {
									child := args.NamedChild(i)
									if child.Kind() == "lambda" {
										refs = append(refs, scopeRefs(path, src, child, owner, name, info)...)
									}
								}
							}
						}
					}
				}
			}
		}
		for i := uint(0); i < n.NamedChildCount(); i++ {
			walk(n.NamedChild(i), namespace, owner)
		}
	}
	walk(tree.RootNode(), "", "")
	return methods, dedup(refs)
}

func scopeName(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if r != '_' && (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') {
				return false
			}
		} else if r != '_' && r != '?' && r != '!' && (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') && (r < '0' || r > '9') {
			return false
		}
	}
	return true
}

func scopeRefs(path string, src []byte, lambda *ts.Node, owner, name string, info ModelInfo) []Ref {
	refs := []Ref{}
	confidence := "candidate"
	if info.Explicit || info.Verified {
		confidence = "inferred"
	}
	var walk func(*ts.Node)
	walk = func(n *ts.Node) {
		if n.Kind() == "call" {
			method := fieldText(n, "method", src)
			receiver := n.ChildByFieldName("receiver")
			if ormMethod(method) && (receiver == nil || receiver.Kind() == "self") {
				line := int(n.StartPosition().Row) + 1
				refs = append(refs, Ref{Path: path, Line: line, Kind: "orm_table", Table: info.Table, Confidence: confidence, Detail: owner + ".scope " + name + " " + method})
				if args := n.ChildByFieldName("arguments"); args != nil {
					for _, column := range ormColumns(args, method, src) {
						refs = append(refs, Ref{Path: path, Line: line, Kind: "orm_column", Table: info.Table, Column: column, Confidence: "candidate", Detail: owner + ".scope " + name + " " + method})
					}
				}
			}
		}
		for i := uint(0); i < n.NamedChildCount(); i++ {
			walk(n.NamedChild(i))
		}
	}
	walk(lambda)
	return refs
}
